+import { prepareCalendarEventSave } from "./calendar-event-save-fields.mjs";
+import {
+  isCalendarEventDraftValid,
+  selectCalendarEventDraftState,
+  setSectionValidity,
+} from "./state/calendarEventDraftSlice.mjs";
+import {
+  operationStarted,
+  operationSucceeded,
+  operationFailed,
+  operationReleased,
+  selectCalendarEventCreateEditSession,
+} from "./state/calendarEventCreateEditSessionSlice.mjs";
+
+const lazy = {};
+ChromeUtils.defineESModuleGetters(lazy, {
+  cal: "resource:///modules/calendar/calUtils.sys.mjs",
+  CalEvent: "resource:///modules/CalEvent.sys.mjs",
+});
+
+/**
+ * Validate and create the current draft through the host's add transaction.
+ * Field helpers own validation, error display, and conversion. Missing title
+ * or date/time helpers leave Save unavailable. Duplicate requests do no work.
+ * Results from a replaced session or draft leave the replacement unchanged.
+ * Failures retain values and row state. The store observer handles closing.
+ *
+ * @param {object} options - The current dialog and host functions.
+ * @param {{getState: () => object, dispatch: (action: object) => void}} options.store
+ *   - The dialog's Redux store.
+ * @param {string} options.sessionKey - The fixed dialog key.
+ * @param {Record<string, CalendarEventSaveField>} [options.fields={}] - Field helpers.
+ * @param {(event: calIEvent) => Promise<void>} options.transact
+ *   - Commit through the existing add transaction and notification path.
+ * @returns {Promise<{status: string}>} Serializable success, invalid, error,
+ *   stale, or unavailable result.
+ */
+export async function saveCalendarEventCreate({
+  store,
+  sessionKey,
+  fields = {},
+  transact,
+}) {
+  const state = store.getState();
+  const session = selectCalendarEventCreateEditSession(state, sessionKey);
+  const draftState = selectCalendarEventDraftState(state, sessionKey);
+  if (
+    session?.mode != "create" ||
+    !["idle", "error"].includes(session.operation.status) ||
+    !draftState?.value ||
+    !fields.title?.validate ||
+    !fields.dateTime?.validate ||
+    !fields.title.apply ||
+    !fields.dateTime.apply
+  ) {
+    return { status: "unavailable" };
+  }
+  const requestId = Services.uuid.generateUUID().toString();
+  const operation = { sessionKey, kind: "save", requestId };
+  const baseline = draftState.baseline;
+  const draft = structuredClone(draftState.value);
+  const isCurrent = () => {
+    const current = store.getState();
+    return (
+      selectCalendarEventDraftState(current, sessionKey)?.baseline ===
+        baseline &&
+      selectCalendarEventCreateEditSession(current, sessionKey)?.operation
+        .requestId === requestId
+    );
+  };
+  store.dispatch(operationStarted(operation));
+  try {
+    if (!isCurrent()) {
+      store.dispatch(operationReleased(operation));
+      return { status: "stale" };
+    }
+    const prepared = prepareCalendarEventSave(draft, fields);
+    for (const [section, field] of Object.entries(fields)) {
+      if (prepared[section].enabled && field.validate) {
+        const validity = field.validate(prepared[section].values);
+        if (!isCurrent()) {
+          store.dispatch(operationReleased(operation));
+          return { status: "stale" };
+        }
+        store.dispatch(setSectionValidity({ sessionKey, section, validity }));
+        if (!isCurrent()) {
+          store.dispatch(operationReleased(operation));
+          return { status: "stale" };
+        }
+      }
+    }
+    const calendar = lazy.cal.manager.getCalendarById(draft.calendarId);
+    const calendarValidity = fields.calendar?.validate
+      ? selectCalendarEventDraftState(store.getState(), sessionKey).validation
+          .calendar
+      : { valid: true };
+    store.dispatch(
+      setSectionValidity({
+        sessionKey,
+        section: "calendar",
+        validity: {
+          ...calendarValidity,
+          valid: calendarValidity.valid && canCreateCalendarEvent(calendar),
+        },
+      })
+    );
+    if (!isCurrent()) {
+      store.dispatch(operationReleased(operation));
+      return { status: "stale" };
+    }
+    if (
+      !isCalendarEventDraftValid(
+        selectCalendarEventDraftState(store.getState(), sessionKey)
+      )
+    ) {
+      store.dispatch(
+        operationFailed({
+          ...operation,
+          error: { code: "event-validation-failed" },
+        })
+      );
+      return { status: "invalid" };
+    }
+    const event = new lazy.CalEvent();
+    event.calendar = calendar;
+    for (const [section, field] of Object.entries(fields)) {
+      if (prepared[section].enabled) {
+        field.apply(event, prepared[section].values);
+      }
+    }
+    if (!isCurrent()) {
+      store.dispatch(operationReleased(operation));
+      return { status: "stale" };
+    }
+    lazy.cal.itip.adaptScheduleAgent(event);
+    event.makeImmutable();
+    await transact(event);
+    if (!isCurrent()) {
+      store.dispatch(operationReleased(operation));
+      return { status: "stale" };
+    }
+    store.dispatch(operationSucceeded(operation));
+    return { status: "success" };
+  } catch (error) {
+    if (!isCurrent()) {
+      store.dispatch(operationReleased(operation));
+      return { status: "stale" };
+    }
+    store.dispatch(
+      operationFailed({ ...operation, error: { code: "event-save-failed" } })
+    );
+    return { status: "error" };
+  }
+}
