+ * Missing field results do not block Save; Save must first call field checks.
+ *
+ * @param {?CalendarEventDraftState} draft - The current draft state.
+ * @returns {boolean} Whether a draft exists and its enabled sections are valid.
+ */
+export function isCalendarEventDraftValid(draft) {
